package rbac

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
	"sync"

	"github.com/ManintheiCloud/Hardex/core/resource"
)

// defaults.json lists the RBAC objects Kubernetes (1.34–1.37) and kubeadm
// create by default, generated by tools/rbac-defaults from the upstream
// bootstrap policy. Regenerate it when a supported Kubernetes version is
// added.
//
//go:embed defaults.json
var defaultsJSON []byte

type defaultsData struct {
	Roles    map[string][]string `json:"roles"`
	Bindings map[string]struct {
		RoleRef  string   `json:"roleRef"`
		Subjects []string `json:"subjects"`
	} `json:"bindings"`
	// Aggregated holds, for each default aggregated ClusterRole, the
	// permissions it has once aggregated and the selectors it uses.
	Aggregated map[string]struct {
		Selectors   []map[string]any `json:"selectors"`
		Permissions []string         `json:"permissions"`
	} `json:"aggregated"`
	// AggregationLabels holds the aggregate-to-* labels of default
	// ClusterRoles (view is aggregated into edit, edit into admin).
	AggregationLabels map[string]map[string]string `json:"aggregationLabels"`
}

var (
	defaultsOnce sync.Once
	defaults     defaultsData
)

func loadDefaults() *defaultsData {
	defaultsOnce.Do(func() {
		if err := json.Unmarshal(defaultsJSON, &defaults); err != nil {
			panic("rbac: embedded defaults.json: " + err.Error())
		}
	})
	return &defaults
}

func objectKey(o *resource.Object) string {
	if o.Kind == "Role" || o.Kind == "RoleBinding" {
		return o.Kind + "/" + o.EffectiveNamespace() + "/" + o.Name
	}
	return o.Kind + "/" + o.Name
}

// isSystem reports whether an RBAC object is a Kubernetes or kubeadm
// default that grants no more than its default definition. Such objects
// are not reported: their broad permissions are by design. The decision is
// by content, never by name or label alone: anyone who can create a
// binding can call it "system:..." or label it as a default, and a default
// binding can be edited to add a subject. Those are assessed like any
// other object.
func isSystem(o *resource.Object) bool {
	d := loadDefaults()
	switch o.Kind {
	case "ClusterRole", "Role":
		want, ok := d.Roles[objectKey(o)]
		if !ok {
			return false
		}
		allowed := map[string]bool{}
		for _, a := range want {
			allowed[a] = true
		}
		if allowed["aggregated"] {
			// admin, edit, view: their rules come from the roles they
			// aggregate, each assessed on its own.
			_, aggregated := resource.Lookup(o.Raw, "aggregationRule")
			return aggregated
		}
		for _, a := range ruleAtoms(resource.Maps(o.Raw, "rules")) {
			if !covered(a, want) {
				return false
			}
		}
		return true
	case "ClusterRoleBinding", "RoleBinding":
		want, ok := d.Bindings[objectKey(o)]
		if !ok {
			return false
		}
		if resource.String(o.Raw, "roleRef", "kind")+"/"+resource.String(o.Raw, "roleRef", "name") != want.RoleRef {
			return false
		}
		allowed := map[string]bool{}
		for _, s := range want.Subjects {
			allowed[s] = true
		}
		for _, s := range resource.Maps(o.Raw, "subjects") {
			if !allowed[defaultSubjectKey(s, o.EffectiveNamespace())] {
				return false
			}
		}
		return true
	}
	return false
}

func defaultSubjectKey(s map[string]any, bindingNS string) string {
	kind, name := resource.String(s, "kind"), resource.String(s, "name")
	if kind == "ServiceAccount" {
		ns := resource.String(s, "namespace")
		if ns == "" {
			ns = bindingNS
		}
		return kind + "/" + ns + "/" + name
	}
	return kind + "/" + name
}

// ruleAtoms expands rules into group|resource|name|verb and url|path|verb
// permissions, as tools/rbac-defaults/generate.py does.
func ruleAtoms(rules []map[string]any) []string {
	var out []string
	for _, r := range rules {
		verbs := resource.Strings(r, "verbs")
		for _, u := range resource.Strings(r, "nonResourceURLs") {
			for _, v := range verbs {
				out = append(out, fmt.Sprintf("url|%s|%s", u, v))
			}
		}
		names := resource.Strings(r, "resourceNames")
		if len(names) == 0 {
			names = []string{"*"}
		}
		for _, g := range resource.Strings(r, "apiGroups") {
			for _, res := range resource.Strings(r, "resources") {
				for _, n := range names {
					for _, v := range verbs {
						out = append(out, fmt.Sprintf("%s|%s|%s|%s", g, res, n, v))
					}
				}
			}
		}
	}
	return out
}

// covered reports whether a permission is granted by a default's
// permissions, where "*" in a default matches any value in that position.
func covered(atom string, defaults []string) bool {
	parts := strings.Split(atom, "|")
	for _, d := range defaults {
		dp := strings.Split(d, "|")
		if len(dp) != len(parts) {
			continue
		}
		ok := true
		for i := range parts {
			if dp[i] != parts[i] && dp[i] != "*" {
				ok = false
				break
			}
		}
		if ok {
			return true
		}
	}
	return false
}
